files.content:
[hidden] { display: none !important; }

:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #a0a0b0;
  --focus: #f5c518;
  --radius: 0px;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  background-image: linear-gradient(45deg, rgba(233,69,96,0.05) 25%, transparent 25%, transparent 75%, rgba(233,69,96,0.05) 75%),
                    linear-gradient(45deg, rgba(233,69,96,0.05) 25%, transparent 25%, transparent 75%, rgba(233,69,96,0.05) 75%);
  background-size: 24px 24px;
  background-position: 0 0, 12px 12px;
  font-family: var(--font);
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.board {
  width: 100%;
  max-width: 640px;
  background: var(--card);
  border: 4px solid var(--accent);
  box-shadow: 8px 8px 0 rgba(0,0,0,0.4);
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.board-header {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  border-bottom: 3px solid var(--accent);
  padding-bottom: 16px;
}

h1 {
  font-size: 1.5rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
}

.period {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 1rem;
}

.period-label {
  color: var(--muted);
  text-transform: uppercase;
  font-size: 0.85rem;
  letter-spacing: 1px;
}

.period-value {
  font-size: 1.5rem;
  font-weight: bold;
  min-width: 2ch;
  text-align: center;
  color: var(--focus);
}

.teams {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}

.team {
  background: rgba(255,255,255,0.03);
  border: 2px solid rgba(233,69,96,0.4);
  padding: 16px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
}

.team h2 {
  font-size: 1rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--muted);
}

.score {
  font-size: 3rem;
  font-weight: bold;
  line-height: 1;
  color: var(--text);
  font-variant-numeric: tabular-nums;
  min-height: 3rem;
}

.controls {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  justify-content: center;
}

button {
  font-family: var(--font);
  font-size: 1rem;
  cursor: pointer;
  border-radius: var(--radius);
  transition: background 0.1s, transform 0.05s, box-shadow 0.1s;
  min-height: 44px;
  min-width: 44px;
}

.score-btn {
  background: var(--accent);
  color: #fff;
  border: 3px solid #b0304a;
  padding: 8px 12px;
  font-weight: bold;
  box-shadow: 3px 3px 0 rgba(0,0,0,0.4);
}

.score-btn:hover { background: #f05a72; }
.score-btn:active { transform: translate(2px, 2px); box-shadow: 1px 1px 0 rgba(0,0,0,0.4); }

.icon-btn {
  background: transparent;
  color: var(--text);
  border: 2px solid var(--muted);
  padding: 4px 10px;
  font-size: 1.25rem;
  font-weight: bold;
}

.icon-btn:hover { border-color: var(--focus); color: var(--focus); }
.icon-btn:active { transform: translate(1px, 1px); }
.icon-btn:disabled { opacity: 0.35; cursor: not-allowed; }

.action-btn {
  background: transparent;
  color: var(--text);
  border: 3px solid var(--muted);
  padding: 10px 20px;
  font-weight: bold;
  text-transform: uppercase;
  letter-spacing: 1px;
  box-shadow: 3px 3px 0 rgba(0,0,0,0.4);
}

.action-btn:hover { border-color: var(--focus); color: var(--focus); }
.action-btn:active { transform: translate(2px, 2px); box-shadow: 1px 1px 0 rgba(0,0,0,0.4); }
.action-btn:disabled { opacity: 0.35; cursor: not-allowed; }

.action-btn.danger { border-color: var(--accent); color: var(--accent); }
.action-btn.danger:hover { background: var(--accent); color: #fff; }

button:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.board-footer {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
  border-top: 3px solid var(--accent);
  padding-top: 16px;
}

@media (max-width: 480px) {
  .teams { grid-template-columns: 1fr; }
  .board { padding: 16px; }
  h1 { font-size: 1.25rem; }
  .score { font-size: 2.5rem; }
}

(function () {
  'use strict';

  var state = {
    scoreA: 0,
    scoreB: 0,
    period: 1,
    history: []
  };

  var els = {
    scoreA: document.getElementById('score-a'),
    scoreB: document.getElementById('score-b'),
    period: document.getElementById('period-value'),
    periodDec: document.getElementById('period-dec'),
    periodInc: document.getElementById('period-inc'),
    undo: document.getElementById('undo'),
    reset: document.getElementById('reset')
  };

  function render() {
    els.scoreA.textContent = state.scoreA;
    els.scoreB.textContent = state.scoreB;
    els.period.textContent = state.period;
    els.periodDec.disabled = state.period <= 1;
    els.periodInc.disabled = state.period >= 4;
    els.undo.disabled = state.history.length === 0;
  }

  function addScore(team, points) {
    var key = team === 'a' ? 'scoreA' : 'scoreB';
    state[key] += points;
    state.history.push({ team: team, points: points });
    render();
  }

  function undo() {
    var last = state.history.pop();
    if (!last) return;
    var key = last.team === 'a' ? 'scoreA' : 'scoreB';
    state[key] -= last.points;
    render();
  }

  function changePeriod(delta) {
    var next = state.period + delta;
    if (next < 1 || next > 4) return;
    state.period = next;
    render();
  }

  function reset() {
    state.scoreA = 0;
    state.scoreB = 0;
    state.period = 1;
    state.history = [];
    render();
  }

  document.querySelectorAll('.score-btn').forEach(function (btn) {
    btn.addEventListener('click', function () {
      addScore(btn.dataset.team, parseInt(btn.dataset.points, 10));
    });
  });

  els.undo.addEventListener('click', undo);
  els.reset.addEventListener('click', reset);
  els.periodDec.addEventListener('click', function () { changePeriod(-1); });
  els.periodInc.addEventListener('click', function () { changePeriod(1); });

  render();
})();
